/* =============================================================================
 * school-engine.js  –  BLE Signal + Period Attendance (9:00–10:00 AM) + Face ID + Library
 *
 * All RSSI values are generated by a mathematical log-distance path-loss model.
 * No Bluetooth hardware is accessed. Face verification is FULLY SIMULATED.
 * Consent-based mock data only. No real biometric data is stored.
 * ========================================================================== */
'use strict';

var SchoolEngine = (function() {

  /* ── Simulation clock ───────────────────────────────────────────────────── */
  var simMinutes = 9 * 60;  // Start at 09:00 AM (Period 1 start)
  var simRunning = false;
  var simSpeed   = 30;      // sim-minutes per real second
  var clockCb    = null;    // callback(minutes)
  var periodCb   = null;    // callback(period|null)
  var lastPeriodId = null;

  function tickClock(dt) {
    if (!simRunning) return;
    simMinutes += dt * simSpeed;
    if (simMinutes >= 24 * 60) simMinutes -= 24 * 60;
    if (clockCb) clockCb(simMinutes);
    _checkPeriodChange();
  }

  function _checkPeriodChange() {
    var p = activePeriod();
    var pid = p ? p.id : null;
    if (pid !== lastPeriodId) {
      lastPeriodId = pid;
      if (periodCb) periodCb(p);
      // Auto-open session for Period 1 or any active period
      if (p) {
        Object.keys(SCHOOL_STUDENTS).forEach(function(cls) {
          _openSession(cls, p.id);
        });
      }
    }
  }

  function activePeriod() {
    var mins = simMinutes;
    for (var i = 0; i < TIMETABLE.length; i++) {
      var p = TIMETABLE[i];
      var st = p.startH * 60 + p.startM, en = p.endH * 60 + p.endM;
      if (mins >= st && mins < en) return p;
    }
    return null;
  }

  function getPeriod1Status() {
    var p1 = TIMETABLE[0]; // Period 1: 9:00 AM to 10:00 AM
    var st = p1.startH * 60 + p1.startM;
    var en = p1.endH * 60 + p1.endM;
    var mins = simMinutes;

    if (mins < st) {
      var minsUntil = Math.ceil(st - mins);
      return {
        state: 'NOT_STARTED',
        name: p1.name,
        subject: p1.subject,
        startStr: '09:00 AM',
        endStr: '10:00 AM',
        statusLabel: 'Attendance Not Started',
        message: 'Attendance opens at 09:00 AM (in ' + minsUntil + 'm)',
        canPunchIn: false,
        remainingMinutes: minsUntil
      };
    } else if (mins < en) {
      var minsLeft = Math.ceil(en - mins);
      return {
        state: 'ACTIVE',
        name: p1.name,
        subject: p1.subject,
        startStr: '09:00 AM',
        endStr: '10:00 AM',
        statusLabel: 'Attendance Session Active',
        message: 'Session closes at 10:00 AM (' + minsLeft + 'm remaining)',
        canPunchIn: true,
        remainingMinutes: minsLeft
      };
    } else {
      return {
        state: 'CLOSED',
        name: p1.name,
        subject: p1.subject,
        startStr: '09:00 AM',
        endStr: '10:00 AM',
        statusLabel: 'Attendance Session Closed',
        message: 'Period 1 session closed at 10:00 AM. Absent records finalized.',
        canPunchIn: false,
        remainingMinutes: 0
      };
    }
  }

  function simTimeStr() {
    var h = Math.floor(simMinutes / 60) % 24;
    var m = Math.floor(simMinutes % 60);
    var ampm = h >= 12 ? 'PM' : 'AM';
    var dispH = h % 12;
    if (dispH === 0) dispH = 12;
    return String(dispH).padStart(2, '0') + ':' + String(m).padStart(2, '0') + ' ' + ampm;
  }

  function simTime24() {
    var h = Math.floor(simMinutes / 60) % 24;
    var m = Math.floor(simMinutes % 60);
    return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
  }

  /* ── Attendance sessions ─────────────────────────────────────────────── */
  // sessions[classId][periodId] = { open, punchIns:{studentId:{ts, faceScore, faceVerified, status}} }
  var sessions = {};
  // libSessions[studentId] = { sessionId, permanentId, classId, name, start, end, status }
  var libSessions = {};
  // presenceState[studentId] = { status, rssi, rawRssi, confidence, lastSeen, roomId, beaconId, allScans }
  var presenceState = {};
  // rssiHistory[studentId] = [rssi, ...]
  var rssiHistory = {};
  // smoothed[studentId] = null|number
  var smoothed = {};
  // faceAttempts[studentId] = { status: 'pending'|'verified'|'failed', score, timestamp }
  var faceAttempts = {};

  function _openSession(classId, periodId) {
    if (!sessions[classId]) sessions[classId] = {};
    if (!sessions[classId][periodId]) {
      sessions[classId][periodId] = { open: true, punchIns: {} };
    } else {
      sessions[classId][periodId].open = true;
    }
  }

  function _closeSession(classId, periodId) {
    if (sessions[classId] && sessions[classId][periodId]) {
      sessions[classId][periodId].open = false;
    }
  }

  /* ── Presence update ─────────────────────────────────────────────────── */
  function _updateStudentPresence(student, simT) {
    var sid = student.id;
    if (!presenceState[sid]) presenceState[sid] = {};
    if (!rssiHistory[sid])   rssiHistory[sid] = [];
    if (smoothed[sid] === undefined) smoothed[sid] = null;

    var beaconId = student.beaconId || ('BCN-' + student.classId);
    var beacon = SCHOOL_BEACONS.find(function(b) { return b.id === beaconId; });
    if (!beacon) return;

    var room = SCHOOL_ROOMS.find(function(r) { return r.id === student.classId; });
    if (!room) return;

    var col = student.col, row2 = student.row;
    var rw = room.x2 - room.x1;
    var sx = room.x1 + 0.9 + col * ((rw - 1.8) / 3);
    var sz = room.z1 + 2.7 + row2 * ((room.z2 - room.z1 - 4.0) / 4);

    var raw = simRSSI(sx, sz, beacon);
    var filt = smoothed[sid] === null ? raw : smoothed[sid] * (1 - SIM.smoothing) + raw * SIM.smoothing;
    smoothed[sid] = filt;
    rssiHistory[sid].push(Math.round(raw));
    if (rssiHistory[sid].length > 120) rssiHistory[sid].shift();

    var allScans = SCHOOL_BEACONS.map(function(b) {
      return { beaconId: b.id, roomId: b.roomId, rssi: simRSSI(sx, sz, b) };
    });
    allScans.sort(function(a, b) { return b.rssi - a.rssi; });
    var strongest = allScans[0];
    var ownScan = allScans.find(function(s) { return s.beaconId === beaconId; });

    var signalStatus, confidence;
    if (!ownScan || filt < SIM.threshold) {
      signalStatus = 'Signal Lost';
      confidence = 0;
    } else if (strongest.beaconId !== beaconId) {
      signalStatus = 'Outside Assigned Room';
      confidence = Math.max(0, Math.round(((filt - SIM.threshold) / (-30 - SIM.threshold)) * 100));
    } else if (filt > -62) {
      signalStatus = 'Strong Signal';
      confidence = Math.min(100, Math.round(((filt - SIM.threshold) / (-30 - SIM.threshold)) * 100));
    } else if (filt > -74) {
      signalStatus = 'Moderate Signal';
      confidence = Math.max(0, Math.round(((filt - SIM.threshold) / (-30 - SIM.threshold)) * 100));
    } else {
      signalStatus = 'Weak Signal';
      confidence = Math.max(0, Math.round(((filt - SIM.threshold) / (-30 - SIM.threshold)) * 100));
    }

    presenceState[sid] = {
      status: signalStatus,
      rssi: Math.round(filt),
      rawRssi: raw,
      confidence: confidence,
      lastSeen: simTime24(),
      roomId: student.classId,
      beaconId: beaconId,
      allScans: allScans.slice(0, 3)
    };
  }

  /* ── Compute attendance status per student ───────────────────────────── */
  function getStudentAttendance(studentId, classId, periodId) {
    periodId = periodId || 'P1';
    var p1Status = getPeriod1Status();
    var punchRec = sessions[classId] && sessions[classId][periodId] && sessions[classId][periodId].punchIns[studentId];
    var face = faceAttempts[studentId] || null;

    if (punchRec) {
      return {
        status: 'PRESENT',
        statusClass: 'status-present',
        label: 'PRESENT',
        punched: true,
        punchTime: punchRec.ts,
        faceScore: punchRec.faceScore || 96,
        faceStatus: 'VERIFIED',
        details: 'Attendance Verified at ' + punchRec.ts
      };
    }

    if (p1Status.state === 'NOT_STARTED') {
      return {
        status: 'NOT_MARKED',
        statusClass: 'status-not-marked',
        label: 'NOT MARKED',
        punched: false,
        punchTime: null,
        faceScore: null,
        faceStatus: face ? face.status.toUpperCase() : 'PENDING',
        details: 'Attendance opens at 09:00 AM'
      };
    }

    if (p1Status.state === 'ACTIVE') {
      return {
        status: 'NOT_MARKED',
        statusClass: 'status-not-marked',
        label: 'NOT MARKED',
        punched: false,
        punchTime: null,
        faceScore: null,
        faceStatus: face ? face.status.toUpperCase() : 'PENDING',
        details: 'Awaiting punch-in (deadline 10:00 AM)'
      };
    }

    // At or after 10:00 AM -> Finalized ABSENT
    return {
      status: 'ABSENT',
      statusClass: 'status-absent',
      label: 'ABSENT',
      punched: false,
      punchTime: null,
      faceScore: null,
      faceStatus: face ? face.status.toUpperCase() : 'MISSED',
      details: 'Failed to punch in before 10:00 AM deadline'
    };
  }

  /* ── Punch-in validation & workflow ───────────────────────────────────── */
  function punchIn(studentId, classId) {
    var p1Status = getPeriod1Status();

    // 1. Period time check
    if (p1Status.state === 'NOT_STARTED') {
      return {
        ok: false,
        msg: 'Attendance Not Started. Opens at 09:00 AM.',
        code: 'PERIOD_NOT_STARTED',
        status: 'Attendance Not Started'
      };
    }
    if (p1Status.state === 'CLOSED') {
      return {
        ok: false,
        msg: 'Attendance Session Closed at 10:00 AM. Punch-ins disabled.',
        code: 'PERIOD_CLOSED',
        status: 'Session Closed'
      };
    }

    // 2. Already punched check
    var periodId = 'P1';
    var sess = sessions[classId] && sessions[classId][periodId];
    if (sess && sess.punchIns[studentId]) {
      return {
        ok: false,
        msg: 'Already punched in at ' + sess.punchIns[studentId].ts,
        code: 'ALREADY_PUNCHED',
        status: 'Already Present'
      };
    }

    // 3. Proximity / BLE Beacon check
    var ps = presenceState[studentId];
    if (!ps || ps.rssi < SIM.threshold) {
      return {
        ok: false,
        msg: 'Classroom BLE beacon (BCN-' + classId + ') not in range or signal lost.',
        code: 'BEACON_LOST',
        status: 'Signal Lost'
      };
    }
    var beacon = SCHOOL_BEACONS.find(function(b) { return b.roomId === classId; });
    if (ps.allScans && beacon && ps.allScans[0] && ps.allScans[0].beaconId !== beacon.id) {
      return {
        ok: false,
        msg: 'Device detected near ' + ps.allScans[0].beaconId + ', but assigned to BCN-' + classId + '.',
        code: 'WRONG_ROOM',
        status: 'Outside Assigned Room'
      };
    }

    // 4. Eligible for Face Verification
    return {
      ok: true,
      needsFace: true,
      msg: 'BLE beacon confirmed. Face verification required.',
      code: 'FACE_REQUIRED',
      status: 'Face Verification Required'
    };
  }

  function completePunchIn(studentId, classId, faceResult) {
    var p1Status = getPeriod1Status();
    if (p1Status.state === 'CLOSED') {
      return { ok: false, msg: 'Attendance deadline (10:00 AM) passed.' };
    }
    if (!faceResult || !faceResult.matched) {
      faceAttempts[studentId] = { status: 'failed', score: faceResult ? faceResult.score : 42, timestamp: simTimeStr() };
      return { ok: false, msg: 'Face verification failed or not matched.', status: 'Verification Failed' };
    }

    var periodId = 'P1';
    if (!sessions[classId]) sessions[classId] = {};
    if (!sessions[classId][periodId]) sessions[classId][periodId] = { open: true, punchIns: {} };

    var ts = simTimeStr();
    sessions[classId][periodId].punchIns[studentId] = {
      ts: ts,
      faceScore: faceResult.score,
      faceVerified: true,
      status: 'punched',
      beaconId: 'BCN-' + classId
    };
    faceAttempts[studentId] = { status: 'verified', score: faceResult.score, timestamp: ts };

    return {
      ok: true,
      msg: 'Attendance marked successfully at ' + ts,
      status: 'PRESENT',
      timestamp: ts,
      faceScore: faceResult.score
    };
  }

  /* ── Face verification (SIMULATED biometric camera) ─────────────────────── */
  function runFaceVerification(studentId) {
    return new Promise(function(resolve) {
      setTimeout(function() {
        var score = Math.round(92 + Math.random() * 7); // 92% - 99%
        var matched = Math.random() > 0.05; // 95% pass rate
        resolve({
          studentId: studentId,
          matched: matched,
          score: matched ? score : Math.round(45 + Math.random() * 25),
          status: matched ? 'Face Verified' : 'Face Mismatch',
          simulated: true,
          disclaimer: 'Consent-based mock biometric verification for demonstration'
        });
      }, 1200 + Math.random() * 500);
    });
  }

  /* ── Library session management ─────────────────────────────────────────── */
  function startLibrarySession(student) {
    var sid = student.id;
    if (libSessions[sid] && libSessions[sid].status === 'active') {
      return { ok: false, msg: 'Library session already active', sessionId: libSessions[sid].sessionId };
    }
    var prevCount = libSessions[sid] ? 2 : 1;
    var sessionId = 'LIB-SESSION-' + sid + '-' + String(prevCount).padStart(3, '0');
    libSessions[sid] = {
      sessionId: sessionId,
      permanentId: sid,
      name: student.name,
      classId: student.classId,
      start: simTimeStr(),
      end: null,
      status: 'active'
    };
    return { ok: true, msg: 'Library session started (' + sessionId + ')', sessionId: sessionId };
  }

  function endLibrarySession(studentId) {
    if (!libSessions[studentId] || libSessions[studentId].status !== 'active') {
      return { ok: false, msg: 'No active library session' };
    }
    libSessions[studentId].end = simTimeStr();
    libSessions[studentId].status = 'ended';
    return { ok: true, msg: 'Library session ended at ' + libSessions[studentId].end };
  }

  /* ── Comprehensive Overview Stats ───────────────────────────────────────── */
  function getOverviewStats() {
    var p1 = getPeriod1Status();
    var total = 0, present = 0, absent = 0, notMarked = 0;
    var faceVerified = 0, facePending = 0, faceFailed = 0;
    var signalLost = 0;

    ['10A', '10B', '10C', '9A', '9B', '9C'].forEach(function(cls) {
      var students = SCHOOL_STUDENTS[cls] || [];
      total += students.length;

      students.forEach(function(s) {
        var att = getStudentAttendance(s.id, cls, 'P1');
        var ps = presenceState[s.id];

        if (att.status === 'PRESENT') {
          present++;
          faceVerified++;
        } else if (att.status === 'ABSENT') {
          absent++;
          facePending++;
        } else {
          notMarked++;
          facePending++;
        }

        if (ps && ps.status === 'Signal Lost') {
          signalLost++;
        }
      });
    });

    var pct = total > 0 ? Math.round((present / total) * 100) : 0;
    var activeLibCount = 0;
    Object.keys(libSessions).forEach(function(k) {
      if (libSessions[k].status === 'active') activeLibCount++;
    });

    return {
      total: total,
      present: present,
      absent: absent,
      notMarked: notMarked,
      faceVerified: faceVerified,
      facePending: facePending,
      faceFailed: faceFailed,
      signalLost: signalLost,
      pct: pct,
      periodStatus: p1,
      simTime: simTimeStr(),
      simTime24: simTime24(),
      simMinutes: simMinutes,
      activeBeacons: SCHOOL_BEACONS.length,
      activeLibSessions: activeLibCount
    };
  }

  function getClassStats(classId) {
    var students = SCHOOL_STUDENTS[classId] || [];
    return students.map(function(s) {
      var ps = presenceState[s.id] || {};
      var att = getStudentAttendance(s.id, classId, 'P1');
      var punchRec = sessions[classId] && sessions[classId]['P1'] && sessions[classId]['P1'].punchIns[s.id];
      return {
        student: s,
        presence: ps,
        attendance: att,
        punchIn: punchRec || null,
        history: rssiHistory[s.id] || []
      };
    });
  }

  function getAllMasterStudents() {
    var all = [];
    ['10A', '10B', '10C', '9A', '9B', '9C'].forEach(function(cls) {
      var students = SCHOOL_STUDENTS[cls] || [];
      students.forEach(function(s) {
        var ps = presenceState[s.id] || {};
        var att = getStudentAttendance(s.id, cls, 'P1');
        var punchRec = sessions[cls] && sessions[cls]['P1'] && sessions[cls]['P1'].punchIns[s.id];
        all.push({
          student: s,
          presence: ps,
          attendance: att,
          punchIn: punchRec || null
        });
      });
    });
    return all;
  }

  function getStudentReport(studentId) {
    var ps = presenceState[studentId] || {};
    var hist = rssiHistory[studentId] || [];
    var student = null;
    Object.keys(SCHOOL_STUDENTS).forEach(function(c) {
      if (!student) student = (SCHOOL_STUDENTS[c] || []).find(function(s) { return s.id === studentId; }) || null;
    });

    var att = student ? getStudentAttendance(studentId, student.classId, 'P1') : null;
    var punchRec = {};
    Object.keys(sessions).forEach(function(cls) {
      Object.keys(sessions[cls]).forEach(function(pid) {
        var rec = sessions[cls][pid].punchIns[studentId];
        if (rec) punchRec[pid] = rec;
      });
    });

    return {
      student: student,
      presence: ps,
      attendance: att,
      history: hist,
      punchins: punchRec,
      libSession: libSessions[studentId] || null
    };
  }

  /* ── Bulk demo helper ───────────────────────────────────────────────────── */
  function autoPunchClass(classId) {
    var students = SCHOOL_STUDENTS[classId] || [];
    var count = 0;
    students.forEach(function(s, idx) {
      if (idx < 16) { // Punch in ~80% of class
        completePunchIn(s.id, classId, {
          matched: true,
          score: Math.round(93 + Math.random() * 6)
        });
        count++;
      }
    });
    return count;
  }

  /* ── Engine tick ────────────────────────────────────────────────────────── */
  function tick(dt, simT) {
    if (!simRunning) return;
    tickClock(dt);

    ['10A', '10B', '10C', '9A', '9B', '9C'].forEach(function(cls) {
      (SCHOOL_STUDENTS[cls] || []).forEach(function(s) {
        _updateStudentPresence(s, simT);
      });
    });

    (SCHOOL_STUDENTS['LIB'] || []).forEach(function(s) {
      var beacon = SCHOOL_BEACONS.find(function(b) { return b.id === 'BCN-LIB'; });
      if (!beacon) return;
      var libRoom = SCHOOL_ROOMS.find(function(r) { return r.id === 'LIB'; });
      if (!libRoom) return;
      var col = s.libCol || 0, row2 = s.libRow || 0;
      var sx = libRoom.x1 + 4 + Math.floor((col * 3) / 3) * 5;
      var sz = libRoom.z1 + 5 + row2 * (row2 < 2 ? 5 : 0);
      var raw = simRSSI(sx, sz, beacon);
      if (!rssiHistory[s.id]) rssiHistory[s.id] = [];
      rssiHistory[s.id].push(raw);
      if (rssiHistory[s.id].length > 120) rssiHistory[s.id].shift();
    });
  }

  /* ── Public API ─────────────────────────────────────────────────────────── */
  return {
    setRunning: function(v) { simRunning = v; },
    isRunning: function() { return simRunning; },
    setSimSpeed: function(v) { simSpeed = v; },
    getSimMinutes: function() { return simMinutes; },
    setSimMinutes: function(v) {
      simMinutes = v;
      if (clockCb) clockCb(simMinutes);
      _checkPeriodChange();
    },
    setSimTime: function(h, m) {
      simMinutes = h * 60 + m;
      if (clockCb) clockCb(simMinutes);
      _checkPeriodChange();
    },
    getSimTimeStr: simTimeStr,
    getSimTime24: simTime24,
    activePeriod: activePeriod,
    getPeriod1Status: getPeriod1Status,
    setClockCb: function(cb) { clockCb = cb; },
    setPeriodCb: function(cb) { periodCb = cb; },
    advancePeriod: function() {
      var p = activePeriod();
      if (p) {
        simMinutes = p.endH * 60 + p.endM + 0.1;
      } else {
        var first = TIMETABLE[0];
        simMinutes = first.startH * 60 + first.startM + 0.1;
      }
      if (clockCb) clockCb(simMinutes);
      lastPeriodId = null;
      _checkPeriodChange();
    },
    tick: tick,
    getPresence: function(sid) { return presenceState[sid] || {}; },
    getAllPresences: function() { return presenceState; },
    getRssiHistory: function(sid) { return rssiHistory[sid] || []; },
    punchIn: punchIn,
    completePunchIn: completePunchIn,
    runFaceVerification: runFaceVerification,
    getStudentAttendance: getStudentAttendance,
    startLibrarySession: startLibrarySession,
    endLibrarySession: endLibrarySession,
    getLibSession: function(sid) { return libSessions[sid] || null; },
    getAllLibSessions: function() { return libSessions; },
    getOverviewStats: getOverviewStats,
    getClassStats: getClassStats,
    getAllMasterStudents: getAllMasterStudents,
    getStudentReport: getStudentReport,
    autoPunchClass: autoPunchClass,
    init: function() {
      simRunning = false;
      simMinutes = 9 * 60; // 09:00 AM
      sessions = {};
      libSessions = {};
      presenceState = {};
      rssiHistory = {};
      smoothed = {};
      faceAttempts = {};

      // Populate initial presence for all students immediately
      ['10A', '10B', '10C', '9A', '9B', '9C'].forEach(function(cls) {
        (SCHOOL_STUDENTS[cls] || []).forEach(function(s) {
          _updateStudentPresence(s, 0);
        });
      });

      // Initialize library sessions for default occupants
      (SCHOOL_STUDENTS['LIB'] || []).slice(0, 6).forEach(function(s) {
        startLibrarySession(s);
      });
    }
  };
})();
